  function openCorrection(record) {
    const identity = record?.source;
    if (!identity?.source_artifact_id) return;
    setNotice(null);
    setCorrection({
      id: identity.source_artifact_id,
      key: identity.logical_source_key,
      role: identity.source_role ?? "",
      version: "",
      jurisdiction: "",
      currentVersion: identity.source_version ?? "",
      currentJurisdiction: identity.jurisdiction ?? "",
    });
  }

  function patchCorrection(partial) {
    setCorrection((prev) => (prev ? { ...prev, ...partial } : prev));
  }

  async function submitCorrection() {
    const editing = correction;
    if (!editing || correctionBusy) return;
    setCorrectionBusy(true);
    setNotice(null);
    const controller = new AbortController();
    correctionControllerRef.current = controller;
    const body = {
      source_role: editing.role,
      source_version: editing.version.trim() || editing.currentVersion || UNMARKED_VERSION,
      jurisdiction: editing.jurisdiction.trim() || editing.currentJurisdiction || UNSPECIFIED_JURISDICTION,
    };
