   Quiet workbench look reusing the app's global design tokens with safe
   fallbacks; body text 16px, UI text 14px, fine print never below 12px. */

.pvs-intake {
  min-width: 0;
  display: grid;
  gap: 12px;
  font-size: 16px;
  color: var(--text, #20242a);
}

.pvs-intake h3,
.pvs-intake p {
  margin: 0;
}

.pvs-head {
  display: grid;
  gap: 4px;
}

.pvs-title {
  font-size: 16px;
  font-weight: 600;
}

.pvs-sub,
.pvs-hint {
  font-size: 12px;
  color: var(--muted, #65707c);
  line-height: 1.5;
}

.pvs-add-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.pvs-add {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 34px;
  padding: 6px 14px;
  border: 1px solid var(--line, #dfe3e8);
  border-radius: 4px;
  background: var(--surface, #ffffff);
  color: var(--text, #20242a);
  font-size: 14px;
  cursor: pointer;
}

.pvs-add:hover {
  border-color: var(--orange, #f37021);
}

.pvs-file-input {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.pvs-intake button {
  font-size: 14px;
  min-height: 30px;
  border-radius: 4px;
  border: 1px solid transparent;
}

.pvs-intake button:focus-visible,
.pvs-intake a:focus-visible,
.pvs-intake select:focus-visible,
.pvs-intake input:focus-visible,
.pvs-intake textarea:focus-visible {
  outline: 2px solid var(--info, #2f6fd6);
  outline-offset: 2px;
}

.pvs-primary {
  padding: 5px 14px;
  background: var(--orange-dark, #d95710);
  color: #ffffff;
}

.pvs-primary:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.pvs-ghost {
  padding: 5px 12px;
  background: var(--surface, #ffffff);
  border-color: var(--line, #dfe3e8);
  color: var(--text, #20242a);
}

.pvs-stage {
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid var(--line, #dfe3e8);
  border-left: 3px solid var(--orange, #f37021);
  border-radius: 4px;
  background: var(--surface, #ffffff);
}

.pvs-stage-name {
  font-size: 14px;
  font-weight: 600;
  word-break: break-all;
}

.pvs-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.pvs-row label {
  font-size: 14px;
  flex: 0 0 auto;
}

.pvs-row select {
  font: inherit;
  font-size: 14px;
  min-height: 30px;
  max-width: 100%;
  padding: 3px 6px;
  border: 1px solid var(--line, #dfe3e8);
  border-radius: 4px;
  background: var(--surface, #ffffff);
  color: var(--text, #20242a);
}

.pvs-brief {
  display: grid;
  gap: 4px;
}

.pvs-brief label {
  font-size: 14px;
}

.pvs-brief textarea {
  font: inherit;
  font-size: 14px;
  resize: vertical;
  padding: 8px 10px;
  border: 1px solid var(--line, #dfe3e8);
  border-radius: 4px;
  background: var(--surface, #ffffff);
  color: var(--text, #20242a);
}

.pvs-cards {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.pvs-card {
  display: grid;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--line, #dfe3e8);
  border-radius: 4px;
  background: var(--surface, #ffffff);
}

.pvs-card-main {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}

.pvs-check {
  flex: 0 0 auto;
  width: 15px;
  height: 15px;
  margin: 3px 0 0;
  accent-color: var(--orange-dark, #d95710);
}

.pvs-card-info {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.pvs-card-name {
  font-size: 15px;
  font-weight: 600;
  word-break: break-all;
}

.pvs-card-meta {
  font-size: 12px;
  color: var(--muted, #65707c);
}

.pvs-card-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding-left: 25px;
}

.pvs-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 14px;
  color: var(--info, #2f6fd6);
  text-decoration: none;
}

.pvs-link:hover {
  text-decoration: underline;
}

.pvs-correct {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--soft-line, #edf0f3);
  border-radius: 4px;
  background: var(--page, #f6f7f9);
}

.pvs-correct-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.pvs-correct-field {
  display: grid;
  gap: 3px;
  min-width: 180px;
}

.pvs-correct-field label {
  font-size: 14px;
}

.pvs-correct-field input {
  font: inherit;
  font-size: 14px;
  min-height: 30px;
  padding: 4px 8px;
  border: 1px solid var(--line, #dfe3e8);
  border-radius: 4px;
  background: var(--surface, #ffffff);
  color: var(--text, #20242a);
  width: 100%;
}

.pvs-ok {
  font-size: 14px;
  color: var(--success, #1f7a42);
  display: grid;
  gap: 4px;
}

.pvs-ok .pvs-ghost {
  justify-self: start;
}

.pvs-error {
  font-size: 14px;
  color: var(--danger, #c92a2a);
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border: 1px solid var(--danger-bg, #fff0f0);
  border-left: 3px solid var(--danger, #c92a2a);
  border-radius: 4px;
  background: var(--danger-bg, #fff0f0);
}

.pvs-error-step {
  font-size: 12px;
  color: var(--muted, #65707c);
}

.pvs-error .pvs-ghost {
  justify-self: start;
}

.pvs-prepare {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding-top: 10px;
  border-top: 1px solid var(--soft-line, #edf0f3);
}

@media (max-width: 560px) {
  .pvs-card-actions {
    padding-left: 0;
  }

  .pvs-row > select {
    flex: 1 1 160px;
  }
