    await waitFor(() => expect(api.listSources).toHaveBeenCalledTimes(2));
    expect(screen.getByText("旧记录.docx")).toBeTruthy();
    expect(screen.queryByRole("button", { name: "保存更正" })).toBeNull();
  });

