 * 方案资料来源录入（V1.1 E04 bounded unit）。
 *
 * A quiet source-intake panel for the personal medical writer.  The actual
 * CRUD/read path is exclusively the injected `api` (createProtocolWorkspaceApi
 * shape): listSources / importSource / correctSourceMetadata /
 * sourceDownloadUrl.  Saved storage is presented as storage only — never as
 * medical admission, quality grading, or model readiness — and every status
 * shown comes from a real API response.
 *
 * Behaviour contracts carried here:
 * - The DOCX file name is the logical source key; version and jurisdiction are
 *   never inferred from the file name and stay server-defaulted (unidentified
 *   / unspecified) until explicitly corrected.
 * - The source role is chosen with human-readable labels before import; there
 *   is no default role, so no classification happens silently.
 * - Corrections PATCH complete metadata (edited role + retained version and
 *   jurisdiction) without re-uploading bytes; conflicts keep the saved record
 *   and surface the server's Chinese message and next step.
 * - A replayed adoption (`replayed: true`) is quiet "already saved" status and
 *   the identity used onwards is `result.current`, never the historical
 *   receipt in `result.source`.
 * - Project switches and unmount abort in-flight uploads/lists and discard
 *   their responses; after an uncertain upload the list is re-read once with
 *   listSources before another upload is suggested (no auto-retry, no
 *   polling).
 * - The writing brief stays owned by the parent through onBriefChange and is
 *   passed back with the selected current source ids via onPrepare; the
 *   prepare action renders only when the parent supplies the callback.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { Download, FilePlus2, PencilLine } from "lucide-react";
import "./ProtocolSourceIntake.css";

const SOURCE_ROLE_OPTIONS = [
  { value: "project_primary", label: "本方案文件（项目方案/研究者手册）" },
  { value: "regulatory_or_guideline", label: "法规或指导原则" },
  { value: "competitor_full_protocol", label: "竞品完整方案" },
  { value: "registry_only", label: "仅试验登记信息" },
  { value: "peer_reviewed", label: "同行评审文献" },
  { value: "company_style_only", label: "公司风格与模板文件" },
  { value: "endpoint_or_instrument", label: "终点定义或评估工具" },
];

const ROLE_LABELS = Object.fromEntries(
  SOURCE_ROLE_OPTIONS.map((option) => [option.value, option.label]),
);

const UNMARKED_VERSION = "unidentified";
const UNSPECIFIED_JURISDICTION = "unspecified";
const FALLBACK_ERROR = "本次操作未能完成，请稍后重试。";

function errorMessageOf(error) {
  return typeof error?.message === "string" && error.message ? error.message : FALLBACK_ERROR;
}

function nextStepOf(error) {
  return typeof error?.detail?.next_step === "string" && error.detail.next_step
    ? error.detail.next_step
    : null;
}

function roleLabel(value) {
  return ROLE_LABELS[value] ?? "资料类别未注明";
}

function versionText(value) {
  return value && value !== UNMARKED_VERSION ? `版本：${value}` : "版本未注明";
}

function jurisdictionText(value) {
  return value && value !== UNSPECIFIED_JURISDICTION ? `地区：${value}` : "地区未注明";
}

function currentOrUnmarked(value) {
  return value && value !== UNMARKED_VERSION && value !== UNSPECIFIED_JURISDICTION ? value : "未注明";
}

