102:            original = next((r for r in records if r.source.source_artifact_id == source_artifact_id), None)
103:            if original is None:
104:                raise LookupError('source_identity_not_found')
105:            values = original.source.model_dump(mode='json')
106:            values.update(source_role=source_role, source_version=source_version, jurisdiction=jurisdiction)
107:            validated = SourceArtifact.model_validate(values)
108:            descriptors = {key: validated.model_dump(mode='json')[key]
109:                           for key in ('source_role', 'source_version', 'jurisdiction')}
110:            same_key = [r for r in records if r.source.logical_source_key == original.source.logical_source_key]
