  return (
    <section className="pvs-intake">
      <header className="pvs-head">
        <h3 className="pvs-title">资料来源</h3>
        <p className="pvs-sub">
          保存Word原文与资料分类，供后续写作使用；医学内容的确认在后续步骤完成。
        </p>
      </header>

      <div className="pvs-add-row">
        <label className="pvs-add">
          <FilePlus2 size={16} aria-hidden="true" />
          添加DOCX文件
          <input
            className="pvs-file-input"
            type="file"
            accept=".docx"
            aria-label="选择要添加的DOCX文件"
            onChange={stageFile}
            disabled={importBusy}
          />
        </label>
        {importStatus && (
          <p className={importStatus.tone === "ok" ? "pvs-ok" : "pvs-error"} role="status">
            {importStatus.text}
          </p>
        )}
      </div>

      {importError && (
        <div className="pvs-error" role="alert">
          <p>{importError.message}</p>
          {importError.nextStep && <p className="pvs-error-step">{importError.nextStep}</p>}
        </div>
      )}

      {pendingFile && (
        <div className="pvs-stage">
          <p className="pvs-stage-name">将添加：{pendingFile.name}</p>
          <p className="pvs-hint">
            以文件名作为资料名称；版本与地区未识别时保持未注明，保存后可随时更正。
          </p>
          <div className="pvs-row">
            <label htmlFor="pvs-import-role">资料类别</label>
            <select
              id="pvs-import-role"
              value={importRole}
              onChange={(event) => setImportRole(event.target.value)}
            >
              <option value="">请选择资料类别</option>
              {SOURCE_ROLE_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
            <button
              type="button"
              className="pvs-primary"
              onClick={confirmImport}
              disabled={!importRole || importBusy}
            >
              {importBusy ? "正在保存…" : "保存到资料"}
            </button>
            <button
              type="button"
              className="pvs-ghost"
              onClick={() => {
                setPendingFile(null);
                setImportRole("");
              }}
              disabled={importBusy}
            >
              取消添加
            </button>
          </div>
        </div>
      )}

      <div className="pvs-brief">
        <label htmlFor="pvs-brief">写作说明（可选）</label>
        <textarea
          id="pvs-brief"
          rows={2}
          value={brief}
          placeholder="补充本次写作的意图或注意事项，可留空。"
          readOnly={!onBriefChange}
          onChange={onBriefChange ? (event) => onBriefChange(event.target.value) : undefined}
        />
      </div>

      {loadError && (
        <div className="pvs-error" role="alert">
          <p>{loadError.message}</p>
          {loadError.nextStep && <p className="pvs-error-step">{loadError.nextStep}</p>}
          <button
            type="button"
            className="pvs-ghost"
            onClick={() => {
              setLoadError(null);
              setReloadToken((token) => token + 1);
            }}
          >
            重试
          </button>
        </div>
      )}

      {sources === null && !loadError && <p className="pvs-hint">正在读取已保存的资料…</p>}

      {sources !== null && currentSources.length === 0 && (
        <p className="pvs-hint">还没有已保存的资料。</p>
      )}

      {currentSources.length > 0 && (
        <ul className="pvs-cards">
          {currentSources.map((record) => {
            const identity = record?.source;
            if (!identity?.source_artifact_id || !identity.logical_source_key) return null;
            const key = identity.logical_source_key;
            const included = !excludedKeys.has(key);
            const editing = correction?.key === key;
            return (
              <li key={identity.source_artifact_id} className="pvs-card">
                <div className="pvs-card-main">
                  <input
                    type="checkbox"
                    className="pvs-check"
                    checked={included}
                    aria-label={`纳入后续写作：${key}`}
                    onChange={(event) => toggleIncluded(key, event.target.checked)}
                  />
                  <div className="pvs-card-info">
                    <span className="pvs-card-name">{key}</span>
                    <span className="pvs-card-meta">
                      {roleLabel(identity.source_role)} · {versionText(identity.source_version)} ·{" "}
                      {jurisdictionText(identity.jurisdiction)}
                    </span>
                  </div>
                </div>
                <div className="pvs-card-actions">
                  <a
                    className="pvs-link"
                    href={apiRef.current.sourceDownloadUrl(projectId, identity.source_artifact_id)}
                    download
                  >
                    <Download size={14} aria-hidden="true" />
                    下载原文件
                  </a>
                  <button
                    type="button"
                    className="pvs-ghost"
                    onClick={() => openCorrection(record)}
                    disabled={correctionBusy}
                  >
                    <PencilLine size={14} aria-hidden="true" />
                    更正类别或版本
                  </button>
                </div>
                {editing && (
                  <div className="pvs-correct">
                    <p className="pvs-hint">
                      更正资料分类，不重新上传文件；原文与历史记录保持不变。
                    </p>
                    <div className="pvs-row">
                      <label htmlFor="pvs-correct-role">更正类别</label>
                      <select
                        id="pvs-correct-role"
                        value={correction.role}
                        onChange={(event) => patchCorrection({ role: event.target.value })}
                      >
                        {SOURCE_ROLE_OPTIONS.map((option) => (
                          <option key={option.value} value={option.value}>
                            {option.label}
                          </option>
                        ))}
                      </select>
                      <button
                        type="button"
                        className="pvs-primary"
                        onClick={submitCorrection}
                        disabled={correctionBusy}
                      >
                        {correctionBusy ? "正在保存…" : "保存更正"}
                      </button>
                      <button
                        type="button"
                        className="pvs-ghost"
                        onClick={() => setCorrection(null)}
                        disabled={correctionBusy}
                      >
                        取消更正
                      </button>
                    </div>
                    <div className="pvs-correct-fields">
                      <div className="pvs-correct-field">
                        <label htmlFor="pvs-correct-version">版本（留空保持原值）</label>
                        <input
                          id="pvs-correct-version"
                          type="text"
                          value={correction.version}
                          onChange={(event) => patchCorrection({ version: event.target.value })}
                        />
                        <span className="pvs-hint">
                          当前：{currentOrUnmarked(correction.currentVersion)}
                        </span>
                      </div>
                      <div className="pvs-correct-field">
                        <label htmlFor="pvs-correct-jurisdiction">地区（留空保持原值）</label>
                        <input
                          id="pvs-correct-jurisdiction"
                          type="text"
                          value={correction.jurisdiction}
                          onChange={(event) =>
                            patchCorrection({ jurisdiction: event.target.value })
                          }
                        />
                        <span className="pvs-hint">
                          当前：{currentOrUnmarked(correction.currentJurisdiction)}
                        </span>
                      </div>
                    </div>
                  </div>
                )}
              </li>
            );
          })}
        </ul>
      )}

      {notice && (
        <div
          className={notice.tone === "error" ? "pvs-error" : "pvs-ok"}
          role={notice.tone === "error" ? "alert" : "status"}
        >
          <p>{notice.message}</p>
          {notice.nextStep && <p className="pvs-error-step">{notice.nextStep}</p>}
          <button type="button" className="pvs-ghost" onClick={() => setNotice(null)}>
            知道了
          </button>
        </div>
      )}

      {typeof onPrepare === "function" && (
        <footer className="pvs-prepare">
          <button
            type="button"
            className="pvs-primary"
            onClick={handlePrepare}
            disabled={prepareDisabled}
          >
            准备写作材料
          </button>
          <span className="pvs-hint">将使用已勾选的 {selectedSourceIds.length} 份资料。</span>
        </footer>
      )}
    </section>
  );
}

