export function ProtocolSourceIntake({
  projectId,
  api,
  brief = "",
  onBriefChange,
  onPrepare,
}) {
  const apiRef = useRef(api);
  useEffect(() => {
    apiRef.current = api;
  });

  const [sources, setSources] = useState(null);
  const [loadError, setLoadError] = useState(null);
  const [reloadToken, setReloadToken] = useState(0);
  const [excludedKeys, setExcludedKeys] = useState(() => new Set());
  const [pendingFile, setPendingFile] = useState(null);
  const [importRole, setImportRole] = useState("");
  const [importBusy, setImportBusy] = useState(false);
  const [importStatus, setImportStatus] = useState(null);
  const [importError, setImportError] = useState(null);
  const [correction, setCorrection] = useState(null);
  const [correctionBusy, setCorrectionBusy] = useState(false);
  const [notice, setNotice] = useState(null);

  const importControllerRef = useRef(null);
  const correctionControllerRef = useRef(null);
  const loadedProjectRef = useRef(null);

  useEffect(() => {
    const controller = new AbortController();
    const projectChanged = loadedProjectRef.current !== projectId;
    loadedProjectRef.current = projectId;
    const stale = () => controller.signal.aborted;
    if (projectChanged) {
      setSources(null);
      setLoadError(null);
      setExcludedKeys(new Set());
      setPendingFile(null);
      setImportRole("");
      setImportStatus(null);
      setImportError(null);
      setCorrection(null);
      setNotice(null);
    }
    apiRef.current
      .listSources(projectId, { signal: controller.signal })
      .then((payload) => {
        if (stale()) return;
        setSources(Array.isArray(payload?.sources) ? payload.sources : []);
        setLoadError(null);
      })
      .catch((error) => {
        if (stale() || error?.name === "AbortError") return;
        setLoadError({ message: errorMessageOf(error), nextStep: nextStepOf(error) });
      });
    return () => {
      controller.abort();
      importControllerRef.current?.abort();
      correctionControllerRef.current?.abort();
    };
  }, [projectId, reloadToken]);

  const currentSources = useMemo(
    () => (Array.isArray(sources) ? sources : []),
    [sources],
  );

  const selectedSourceIds = useMemo(
    () =>
      currentSources
        .filter(
          (record) =>
            record?.source?.logical_source_key &&
            !excludedKeys.has(record.source.logical_source_key),
        )
        .map((record) => record.source.source_artifact_id),
    [currentSources, excludedKeys],
  );

  const prepareDisabled = sources === null || importBusy || correctionBusy;

  function applyCurrentRecord(stored) {
    const identity = stored?.source;
    if (!identity?.logical_source_key) return;
    const key = identity.logical_source_key;
    setSources((prev) => {
      const base = Array.isArray(prev) ? prev : [];
      return [...base.filter((record) => record?.source?.logical_source_key !== key), stored];
    });
    setExcludedKeys((prev) => {
      if (!prev.has(key)) return prev;
      const next = new Set(prev);
      next.delete(key);
      return next;
    });
  }

  async function refreshSources(signal) {
    try {
      const payload = await apiRef.current.listSources(projectId, { signal });
      if (signal?.aborted) return;
      setSources(Array.isArray(payload?.sources) ? payload.sources : []);
      setLoadError(null);
    } catch (error) {
      if (signal?.aborted || error?.name === "AbortError") return;
      setLoadError({ message: errorMessageOf(error), nextStep: nextStepOf(error) });
    }
  }

  function stageFile(event) {
    const file = event.target.files?.[0] ?? null;
    event.target.value = "";
    setImportStatus(null);
    setImportError(null);
    if (!file) {
      setPendingFile(null);
      return;
    }
    if (!/\.docx$/i.test(file.name)) {
      setPendingFile(null);
      setImportError({
        message: "请选择DOCX格式的Word文件。",
        nextStep: "请在Word中确认后另存为DOCX，再重新选择。",
      });
      return;
    }
    setPendingFile(file);
    setImportRole("");
  }

  async function confirmImport() {
    const file = pendingFile;
    if (!file || !importRole || importBusy) return;
    setImportBusy(true);
    setImportError(null);
    setImportStatus(null);
    setNotice(null);
    const controller = new AbortController();
    importControllerRef.current = controller;
    try {
      const result = await apiRef.current.importSource(
        projectId,
        {
          file,
          logicalSourceKey: file.name,
          sourceRole: importRole,
          sourceVersion: "",
          jurisdiction: "",
        },
        { signal: controller.signal },
      );
      if (controller.signal.aborted) return;
      // The current identity (not the historical receipt) becomes the card.
      applyCurrentRecord(result?.current ?? null);
      setImportStatus(
        result?.replayed
          ? { tone: "ok", text: "这份文件此前已保存，已在当前资料中。" }
          : { tone: "ok", text: "已保存。" },
      );
      setPendingFile(null);
      setImportRole("");
    } catch (error) {
      if (controller.signal.aborted || error?.name === "AbortError") return;
      setImportError({ message: errorMessageOf(error), nextStep: nextStepOf(error) });
      // The upload outcome is uncertain (the server may still have saved it):
      // re-read the list once before suggesting another upload.
      await refreshSources(controller.signal);
    } finally {
      if (!controller.signal.aborted) setImportBusy(false);
    }
  }

  function openCorrection(record) {
    const identity = record?.source;
    if (!identity?.source_artifact_id) return;
    setNotice(null);
    setCorrection({
      id: identity.source_artifact_id,
      key: identity.logical_source_key,
      role: identity.source_role ?? "",
      version: "",
      jurisdiction: "",
      currentVersion: identity.source_version ?? "",
      currentJurisdiction: identity.jurisdiction ?? "",
    });
  }

  function patchCorrection(partial) {
    setCorrection((prev) => (prev ? { ...prev, ...partial } : prev));
  }

  async function submitCorrection() {
    const editing = correction;
    if (!editing || correctionBusy) return;
    setCorrectionBusy(true);
    setNotice(null);
    const controller = new AbortController();
    correctionControllerRef.current = controller;
    const body = {
      source_role: editing.role,
      source_version: editing.version.trim() || editing.currentVersion || UNMARKED_VERSION,
      jurisdiction: editing.jurisdiction.trim() || editing.currentJurisdiction || UNSPECIFIED_JURISDICTION,
    };
    try {
      const result = await apiRef.current.correctSourceMetadata(
        projectId,
        editing.id,
        body,
        { signal: controller.signal },
      );
      if (controller.signal.aborted) return;
      if (!result?.replayed) applyCurrentRecord(result?.current ?? null);
      setCorrection(null);
      setNotice(
        result?.replayed
          ? { tone: "ok", message: "资料信息未变化，无需更正。" }
          : { tone: "ok", message: "已保存更正。" },
      );
    } catch (error) {
      if (controller.signal.aborted || error?.name === "AbortError") return;
      // The saved record is untouched server-side; surface the server's own
      // explanation and next step, then re-read the list once so the current
      // version is what the user sees.
      setCorrection(null);
      setNotice({
        tone: "error",
        message: errorMessageOf(error),
        nextStep: nextStepOf(error),
      });
      await refreshSources(controller.signal);
    } finally {
      if (!controller.signal.aborted) setCorrectionBusy(false);
    }
  }

  function toggleIncluded(key, included) {
    setExcludedKeys((prev) => {
      const next = new Set(prev);
      if (included) next.delete(key);
      else next.add(key);
      return next;
    });
  }

  function handlePrepare() {
    if (typeof onPrepare !== "function" || prepareDisabled) return;
    onPrepare({ userBrief: brief, sourceArtifactIds: [...selectedSourceIds] });
  }

  return (
    <section className="pvs-intake">
      <header className="pvs-head">
        <h3 className="pvs-title">资料来源</h3>
        <p className="pvs-sub">","truncated":true,"truncatedBy":"lines","totalLines":512,"totalBytes":8341,"outputLines":256,"outputBytes":8341,"lastLinePartial":false,"firstLineExceedsLimit":false},"totalLines":589,"displayContent":{"text":"
