46:export async function requestJsonWithTimeout(
47:  url,
48:  options = {},
49:  {
50:    timeoutMs = COMMAND_REQUEST_TIMEOUT_MS,
51:    signal,
52:    fetchImpl = fetch,
53:  } = {},
54:) {
55:  const controller = new AbortController();
56:  let timedOut = false;
57:  const abortFromCaller = () => controller.abort();
58:  if (signal?.aborted) controller.abort();
59:  else signal?.addEventListener("abort", abortFromCaller, { once: true });
60:  const timeoutId = setTimeout(() => {
61:    timedOut = true;
62:    controller.abort();
63:  }, timeoutMs);
64:  try {
65:    const response = await fetchImpl(url, { ...options, signal: controller.signal });
66:    return await readJson(response);
67:  } catch (error) {
68:    if (timedOut) {
69:      throw new SynopsisRequestTimeoutError(`请求在 ${Math.ceil(timeoutMs / 1000)} 秒内未响应`);
70:    }
71:    throw error;
72:  } finally {
73:    clearTimeout(timeoutId);
74:    signal?.removeEventListener("abort", abortFromCaller);
75:  }
76:}
