        {
          "design.interim_analysis": "不设置期中分析",
          "design.randomization": "随机",
          "design.blinding": "双盲",
        },
        {},
      ),
    ).toEqual({
      "design.randomization": "随机",
      "design.blinding": "双盲",
      "design.interim_analysis": "不设置期中分析",
    });
