  return (
    <section className="pvs-intake">
      <header className="pvs-head">
        <h3 className="pvs-title">资料来源</h3>
        <p className="pvs-sub">
          保存Word原文与资料分类，供后续写作使用；医学内容的确认在后续步骤完成。
        </p>
      </header>

      <div className="pvs-add-row">
        <label className="pvs-add">
          <FilePlus2 size={16} aria-hidden="true" />
          添加DOCX文件
          <input
            className="pvs-file-input"
            type="file"
            accept=".docx"
            aria-label="选择要添加的DOCX文件"
            onChange={stageFile}
            disabled={importBusy}
          />
        </label>
        {importStatus && (
          <p className={importStatus.tone === "ok" ? "pvs-ok" : "pvs-error"} role="status">
            {importStatus.text}
          </p>
        )}
      </div>

      {importError && (
        <div className="pvs-error" role="alert">
          <p>{importError.message}</p>
          {importError.nextStep && <p className="pvs-error-step">{importError.nextStep}</p>}
        </div>
      )}

      {pendingFile && (
        <div className="pvs-stage">
          <p className="pvs-stage-name">将添加：{pendingFile.name}</p>
          <p className="pvs-hint">
            以文件名作为资料名称；版本与地区未识别时保持未注明，保存后可随时更正。
          </p>
          <div className="pvs-row">
            <label htmlFor="pvs-import-role">资料类别</label>
            <select
              id="pvs-import-role"
              value={importRole}
              onChange={(event) => setImportRole(event.target.value)}
            >
              <option value="">请选择资料类别</option>
              {SOURCE_ROLE_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
            <button
              type="button"
              className="pvs-primary"
              onClick={confirmImport}
              disabled={!importRole || importBusy}
            >
              {importBusy ? "正在保存…" : "保存到资料"}
            </button>
            <button
              type="button"
              className="pvs-ghost"
              onClick={() => {
                setPendingFile(null);
                setImportRole("");
              }}
              disabled={importBusy}
            >
              取消添加
            </button>
          </div>
        </div>
      )}

      <div className="pvs-brief">
