            accept=".docx"
            aria-label="选择要添加的DOCX文件"
            onChange={stageFile}
            disabled={importBusy}
          />
        </label>
        {importStatus && (
          <p className={importStatus.tone === "ok" ? "pvs-ok" : "pvs-error"} role="status">
            {importStatus.text}
          </p>
        )}
      </div>

