    }
    if (typeof file.name !== "string" || !/\.docx$/iu.test(file.name)) {
      setPendingFile(null);
      setImportRole("");
      setImportError({
        message: "请选择DOCX格式的Word文件。",
        nextStep: "请在Word中确认后另存为DOCX，再重新选择。",
