          </div>
          <p className="pvs-hint" id={ids.importRoleHint}>
            请选择最符合文件用途的类别；选择类别不代表确认其中的医学内容。
          </p>
        </div>
      )}

      <div className="pvs-brief">
        <label htmlFor={ids.brief}>写作说明（可选）</label>
        <textarea
          id={ids.brief}
          rows={2}
          maxLength={500}
          value={brief}
