    setViewProjectId(scope.projectId);
    setSources(null);
    setSourcesProjectId(null);
    setLoadError(null);
    setExcludedKeys(new Set());
    setPendingFile(null);
    setImportRole("");
    setImportBusyState(false);
    setImportStatus(null);
    setImportError(null);
    setCorrection(null);
    setCorrectionBusyState(false);
