    requestApi.listSources(scope.projectId, { signal: controller.signal })
      .then((payload) => {
        if (!isLive(scope, controller.signal)) return;
        acceptSourceList(sourceListFrom(payload), scope);
        setLoadError(null);
      })
      .catch((error) => {
