41:    correctSourceMetadata: vi.fn(correctImpl ?? (async () => ({ replayed: false }))),
42:    sourceDownloadUrl: (projectId, sourceArtifactId) =>
43:      `/api/projects/${projectId}/protocol-workflow/sources/${encodeURIComponent(String(sourceArtifactId))}/content`,
44:  };
45:}
