    expect(p1Signal.aborted).toBe(true);

    p1Deferred.resolve({ sources: [sourceRecord({ id: "s-late", key: "迟到文件.docx" })] });
    await new Promise((resolve) => setTimeout(resolve, 0));
    expect(screen.queryByText(/迟到文件/)).toBeNull();
  });

