```jsx
<ProtocolSourceIntake
  projectId={projectId}
  api={createProtocolWorkspaceApi(...)}
  brief={brief}
  onBriefChange={(next) => setBrief(next)}
  onPrepare={({ userBrief, sourceArtifactIds }) => { /* owner flow */ }}
/>
```

