35:export function createProtocolWorkspaceApi({ fetchImpl = globalThis.fetch } = {}) {
36:  if (typeof fetchImpl !== "function") {
37:    throw new ProtocolWorkspaceApiError("当前环境不支持方案工作台请求。");
38:  }
39:
40:  const request = async (path, options = {}) => {
41:    let response;
42:    try {
43:      response = await fetchImpl(path, {
44:        ...options,
45:        headers: { Accept: "application/json", ...(options.headers || {}) },
46:      });
47:    } catch (error) {
48:      if (error && error.name === "AbortError") throw error;
49:      // Network/transport failures never leak the underlying (possibly
50:      // English/program) message into user-facing copy.
51:      throw new ProtocolWorkspaceApiError("方案工作台请求失败。", {
52:        status: 0,
53:        detail: null,
54:      });
55:    }
56:    let payload = null;
57:    try {
58:      payload = await response.json();
59:    } catch {
60:      throw new ProtocolWorkspaceApiError(
61:        "方案工作台返回内容无法解析，本次请求未能完成。",
62:        { status: response.status, detail: null },
63:      );
64:    }
65:    if (!response.ok) {
66:      const rawDetail = payload && typeof payload === "object" ? payload.detail : null;
67:      // Normalize defensively: keep ONLY the four approved public fields
68:      // (message / responsible_area / can_retry / next_step) and discard any
69:      // top-level or nested audit-shaped key (machine codes, object ids,
70:      // attempts, owners, recovery actions, audit detail/context).
71:      let detail = null;
72:      if (rawDetail && typeof rawDetail === "object") {
73:        const normalized = {};
74:        if (typeof rawDetail.message === "string") normalized.message = rawDetail.message;
75:        if (typeof rawDetail.responsible_area === "string") normalized.responsible_area = rawDetail.responsible_area;
76:        if (typeof rawDetail.can_retry === "boolean") normalized.can_retry = rawDetail.can_retry;
77:        if (typeof rawDetail.next_step === "string") normalized.next_step = rawDetail.next_step;
78:        if (Object.keys(normalized).length > 0) detail = normalized;
79:      }
80:      const message =
81:        detail && typeof detail.message === "string"
82:          ? detail.message
83:          : "方案工作台未能完成本次操作。";
84:      throw new ProtocolWorkspaceApiError(message, {
85:        status: response.status,
86:        detail,
87:      });
88:    }
89:    return payload;
90:  };
