        next.filter(isStoredSource).map((record) => record.source.logical_source_key),
      );
      const retained = new Set(
        [...previous].filter((key) => currentKeys.has(key)),
      );
      if (retained.size === previous.size && [...retained].every((key) => previous.has(key))) {
